/** ბირთვი_მნიშვნელობა 안의 연결형 ბაიტი_მნიშვნელობა ნაკადი_მნიშვნელობა. Ethernet/TCP 패킷 스택이 아닌 루프백 socket შრე_მნიშვნელობა. */
public final class ნაკადი_ქსელი {
    static int[] სტატუსი_მნიშვნელობა = new int[16], პორტი_მნიშვნელობა = new int[16], 짝 = new int[16], კვანძი_პორტი = new int[16], მოლოდინი_მნიშვნელობა = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], მონაცემები = new int[16 * 1024];
    static int შემდეგი_ელემენტი = 50000;
    static int გადამოწმება(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && სტატუსი_მნიშვნელობა[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int 접속번호) { for (int ციკლი_ინდექსი = 0; ციკლი_ინდექსი < 16; ციკლი_ინდექსი++) if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] != 0 && 묶임[ციკლი_ინდექსი] != 0 && პორტი_მნიშვნელობა[ციკლი_ინდექსი] == 접속번호) return true; return false; }
    public static int შექმნა_შენატანი() {
        for (int ციკლი_ინდექსი = 0; ციკლი_ინდექსი < 16; ციკლი_ინდექსი++) if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] == 0) { სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] = 1; კვანძი_პორტი[ციკლი_ინდექსი] = პორტი_მნიშვნელობა[ციკლი_ინდექსი] = 앞[ციკლი_ინდექსი] = 수[ციკლი_ინდექსი] = მოლოდინი_მნიშვნელობა[ციკლი_ინდექსი] = 묶임[ციკლი_ინდექსი] = 0; 짝[ციკლი_ინდექსი] = -1; return ციკლი_ინდექსი + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int 접속번호) {
        int ციკლი_ინდექსი = გადამოწმება(열린파일번호); if (ციკლი_ინდექსი < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] != 1 || 접속번호 < 0 || 접속번호 > 65535) return -22;
        if (접속번호 == 0) { do { 접속번호 = შემდეგი_ელემენტი++; if (შემდეგი_ელემენტი > 65535) შემდეგი_ელემენტი = 50000; } while (사용중(접속번호)); }
        if (사용중(접속번호)) return -98; პორტი_მნიშვნელობა[ციკლი_ინდექსი] = 접속번호; 묶임[ციკლი_ინდექსი] = 1; სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int ციკლი_ინდექსი = გადამოწმება(열린파일번호); if (ციკლი_ინდექსი < 0) return -9; if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] != 2 || 연결대기한도 < 1) return -22; სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] = 3; return 0; }
    public static int დაკავშირება(int 열린파일번호, int 통신주소, int 접속번호) {
        int ციკლი_ინდექსი = გადამოწმება(열린파일번호); if (ციკლი_ინდექსი < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (접속번호 < 1 || 접속번호 > 65535 || სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] > 2) return -22;
        int 수신쪽 = -1; for (int შიდა_შეერთება_პოზიცია = 0; შიდა_შეერთება_პოზიცია < 16; შიდა_შეერთება_პოზიცია++) if (სტატუსი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] == 3 && პორტი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] == 접속번호) 수신쪽 = შიდა_შეერთება_პოზიცია;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int შიდა_შეერთება_პოზიცია = 0; შიდა_შეერთება_პოზიცია < 16; შიდა_შეერთება_პოზიცია++) if (მოლოდინი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = შექმნა_შენატანი(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] = სტატუსი_მნიშვნელობა[다른번호] = 4; 짝[ციკლი_ინდექსი] = 다른번호; 짝[다른번호] = ციკლი_ინდექსი; პორტი_მნიშვნელობა[다른번호] = 접속번호; კვანძი_პორტი[ციკლი_ინდექსი] = 접속번호; კვანძი_პორტი[다른번호] = პორტი_მნიშვნელობა[ციკლი_ინდექსი]; მოლოდინი_მნიშვნელობა[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int მიღება_კავშირი(int 열린파일번호) { int ციკლი_ინდექსი = გადამოწმება(열린파일번호); if (ციკლი_ინდექსი < 0) return -9; if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] != 3) return -22; for (int შიდა_შეერთება_პოზიცია = 0; შიდა_შეერთება_პოზიცია < 16; შიდა_შეერთება_პოზიცია++) if (სტატუსი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] != 0 && მოლოდინი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] == ციკლი_ინდექსი + 1) { მოლოდინი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] = 0; return შიდა_შეერთება_პოზიცია + 40; } return -11; }
    public static int ჩაწერა(int 열린파일번호, int 항목수) {
        int ციკლი_ინდექსი = გადამოწმება(열린파일번호); if (ციკლი_ინდექსი < 0) return -9; if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int შიდა_შეერთება_პოზიცია = 짝[ციკლი_ინდექსი]; if (შიდა_შეერთება_პოზიცია < 0) return -32; int 총수 = 1024 - 수[შიდა_შეერთება_პოზიცია]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int 비교자리 = 0; 비교자리 < 총수; 비교자리++) მონაცემები[შიდა_შეერთება_პოზიცია * 1024 + (앞[შიდა_შეერთება_პოზიცია] + 수[შიდა_შეერთება_პოზიცია] + 비교자리) % 1024] = 되돌림망.გადაგზავნა_მნიშვნელობა[비교자리]; 수[შიდა_შეერთება_პოზიცია] += 총수; return 총수;
    }
    public static int კითხვა(int 열린파일번호, int 항목수) {
        int ციკლი_ინდექსი = გადამოწმება(열린파일번호); if (ციკლი_ინდექსი < 0) return -9; if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[ციკლი_ინდექსი] == 0) return 짝[ციკლი_ინდექსი] < 0 ? 0 : -11; if (항목수 > 수[ციკლი_ინდექსი]) 항목수 = 수[ციკლი_ინდექსი];
        for (int 비교자리 = 0; 비교자리 < 항목수; 비교자리++) 되돌림망.გადაგზავნა_მნიშვნელობა[비교자리] = მონაცემები[ციკლი_ინდექსი * 1024 + (앞[ციკლი_ინდექსი] + 비교자리) % 1024]; 앞[ციკლი_ინდექსი] = (앞[ციკლი_ინდექსი] + 항목수) % 1024; 수[ციკლი_ინდექსი] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int ციკლი_ინდექსი = გადამოწმება(열린파일번호); return ციკლი_ინდექსი < 0 ? -9 : პორტი_მნიშვნელობა[ციკლი_ინდექსი]; }
    public static int 상대창구읽기(int 열린파일번호) { int ციკლი_ინდექსი = გადამოწმება(열린파일번호); return ციკლი_ინდექსი < 0 ? -9 : კვანძი_პორტი[ციკლი_ინდექსი]; }
    public static int დახურვა(int 열린파일번호) {
        int ციკლი_ინდექსი = გადამოწმება(열린파일번호); if (ციკლი_ინდექსი < 0) return -9;
        if (სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] == 3) for (int შიდა_შეერთება_პოზიცია = 0; შიდა_შეერთება_პოზიცია < 16; შიდა_შეერთება_პოზიცია++) if (მოლოდინი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] == ციკლი_ინდექსი + 1) { if (짝[შიდა_შეერთება_პოზიცია] >= 0) 짝[짝[შიდა_შეერთება_პოზიცია]] = -1; სტატუსი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] = მოლოდინი_მნიშვნელობა[შიდა_შეერთება_პოზიცია] = 묶임[შიდა_შეერთება_პოზიცია] = 0; }
        if (짝[ციკლი_ინდექსი] >= 0) 짝[짝[ციკლი_ინდექსი]] = -1; სტატუსი_მნიშვნელობა[ციკლი_ინდექსი] = 묶임[ციკლი_ინდექსი] = 수[ციკლი_ინდექსი] = მოლოდინი_მნიშვნელობა[ციკლი_ინდექსი] = 0; return 0;
    }
}
